document.getElementById('prpRunChainBtn')?.addEventListener('click',async function(){
const payload=collectProposalDom();
if(!payload.client_name&&!payload.client_company){
toast('Otomasyon zincirini başlatmadan önce müşteri adı veya firma ünvanını girin.',true);
return;
}
const btn=this;
btn.disabled=true;
btn.textContent='⏳ 4 Adımlı Zincir Kuruluyor...';
try{
let targetId=payload.id||'';
const saveRes=await api('proposal_save',{proposal:payload});
if(saveRes.proposals)S.proposals=saveRes.proposals;
if(saveRes.proposal){
S.editingProposal=saveRes.proposal;
targetId=saveRes.proposal.id||saveRes.proposal.code;
}
const chainRes=await api('proposal_run_automation_chain',{
id:targetId||payload.code,
target_domain:payload.target_domain||'',
annual_renewal_amount:payload.annual_renewal_amount||0,
client_tax_office:payload.client_tax_office||'',
client_tax_no:payload.client_tax_no||'',
client_address:payload.client_address||''
});
applyChainApiResponseToState(chainRes);
if(chainRes.proposal)S.editingProposal=chainRes.proposal;
toast(chainRes.message);
renderProposalsStudioView();
}catch(err){
toast(err.message,true);
btn.disabled=false;
btn.textContent='⚡ 4 Adımlı Otomasyon Zincirini Başlat';
}
});
